import { createSelector } from '@reduxjs/toolkit';
import { useAppSelector } from '06_shared/hooks/useAppSelector';
const ZERO_TOTAL = {
    available_balance: 0,
    total_margin_balance: 0,
    total_unrealized_profit: 0,
    total_wallet_balance: 0,
};
// Голий useAppSelector із reduce повертав новий обʼєкт на кожен рендер.
// Селектор типізовано локальною схемою, щоб не перетнути межу шарів.
const selectAccountBalanceTotal = createSelector((accountBalance) => accountBalance?.account_balance_dict, (account_balance_dict) => {
    if (!account_balance_dict)
        return ZERO_TOTAL;
    return Object.values(account_balance_dict).reduce((acc, curr) => {
        return {
            available_balance: acc.available_balance + curr.available_balance,
            total_margin_balance: acc.total_margin_balance + curr.total_margin_balance,
            total_unrealized_profit: acc.total_unrealized_profit + curr.total_unrealized_profit,
            total_wallet_balance: acc.total_wallet_balance + curr.total_wallet_balance,
        };
    }, ZERO_TOTAL);
});
const useGetAccountBalanceTotal = () => {
    const accountBalance = useAppSelector((state) => state.accountBalance);
    return selectAccountBalanceTotal(accountBalance);
};
export { useGetAccountBalanceTotal };
