import { createSlice, } from '@reduxjs/toolkit';
const initialState = {
    account_balance_dict: {},
};
export const accountBalanceSlice = createSlice({
    name: 'accountBalance',
    initialState,
    reducers: {
        setAccountBalance: (state, action) => {
            state.account_balance_dict[action.payload.platform_uuid] = action.payload;
        },
        removeAccountBalance: (state, action) => {
            delete state.account_balance_dict[action.payload];
        },
        resetAccountBalanceSlice() {
            return initialState;
        },
    }
});
export const { actions: accountBalanceActions } = accountBalanceSlice;
export const { reducer: accountBalanceReducer } = accountBalanceSlice;
