import { useCallback, useEffect } from 'react';
import { useGetMe } from '06_shared/hooks/useGetMe';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { useGetPinCodeByPlatformUUID } from '05_entities/pinCode';
import { useLazyGetAccountBalanceServerQuery } from '../api/accountBalanceApi';
import { accountBalanceActions } from '../slice/accountBalanceSlice';
const useGetAccountBalanceServer = (platform_uuid) => {
    const dispatch = useAppDispatch();
    const [getAccountBalance, { data, isLoading, isError }] = useLazyGetAccountBalanceServerQuery();
    const user = useGetMe();
    const pin_code = useGetPinCodeByPlatformUUID(platform_uuid);
    const getAccountBalanceServer = useCallback(async () => {
        try {
            if (!user || !pin_code) {
                dispatch(accountBalanceActions.removeAccountBalance(platform_uuid));
                return;
            }
            const payload = {
                pin_code: pin_code,
                platform_uuid,
            };
            getAccountBalance(payload);
        }
        catch {
            dispatch(accountBalanceActions.removeAccountBalance(platform_uuid));
        }
    }, [dispatch, getAccountBalance, pin_code, platform_uuid, user]);
    useEffect(() => {
        if (data?.result) {
            dispatch(accountBalanceActions.setAccountBalance(data.result));
        }
    }, [data, dispatch]);
    useEffect(() => {
        if (isError) {
            dispatch(accountBalanceActions.removeAccountBalance(platform_uuid));
        }
    }, [dispatch, isError, platform_uuid]);
    return {
        getAccountBalanceServer,
        isLoading,
    };
};
export { useGetAccountBalanceServer };
