import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const accountBalanceApi = createApi({
    reducerPath: 'accountBalanceApi',
    tagTypes: ['accountBalanceServer'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getAccountBalanceServer: builder.query({
            query: (body) => ({
                url: '/account-balance',
                method: RequestMethods.POST,
                body,
            }),
            providesTags: ['accountBalanceServer'],
        }),
    }),
});
export const { useLazyGetAccountBalanceServerQuery, } = accountBalanceApi;
