import { useCallback, useState } from 'react';
import { useGetPinCodeByPlatformUUID } from '05_entities/pinCode';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { TradeTokenLevelEnum, useGetTradeTokenByPlatformUUID, } from '05_entities/tradeToken';
import { notificationActions } from '05_entities/notification';
import { NOTIFICATION_KEYS } from '06_shared/constants/notificationKeys';
import { BinanceFAPI } from '06_shared/api/binanceFAPI';
import { accountBalanceActions } from '../slice/accountBalanceSlice';
import { decodeString } from '06_shared/utils/cryptoJSUtils';
import { serviceErrorHandler } from '06_shared/utils/serviceErrorHandler';
import { useGetMe } from '06_shared/hooks/useGetMe';
const useGetAccountBalanceClient = (platform_uuid) => {
    const dispatch = useAppDispatch();
    const [isLoading, setIsLoading] = useState(false);
    const user = useGetMe();
    const pin_code = useGetPinCodeByPlatformUUID(platform_uuid);
    const trade_token = useGetTradeTokenByPlatformUUID(platform_uuid);
    const getAccountBalanceClient = useCallback(async () => {
        if (!pin_code)
            return;
        if (!trade_token)
            return;
        if (trade_token.level !== TradeTokenLevelEnum.TRADE_AVAILABLE)
            return;
        if (!user) {
            dispatch(notificationActions.addNotificationItem({
                type: 'Error',
                description: [NOTIFICATION_KEYS.CURRENT_USER_NOT_FOUND],
            }));
            return;
        }
        const trade_token_encoded_string = localStorage.getItem(platform_uuid);
        if (!trade_token_encoded_string) {
            dispatch(notificationActions.addNotificationItem({
                type: 'Error',
                description: [NOTIFICATION_KEYS.TRADE_TOKEN_NOT_FOUND],
            }));
            return;
        }
        try {
            setIsLoading(true);
            const key = `${pin_code}${user.user_trade_token_key}`;
            const trade_token_decoded_string = await decodeString(trade_token_encoded_string, key);
            const trade_token_decoded_dict = JSON.parse(trade_token_decoded_string);
            const binance_fapi = new BinanceFAPI(trade_token_decoded_dict.api_key, trade_token_decoded_dict.api_secret);
            const account = await binance_fapi.getAccount();
            dispatch(accountBalanceActions.setAccountBalance({
                platform_uuid,
                available_balance: parseFloat(account.availableBalance),
                total_margin_balance: parseFloat(account.totalMarginBalance),
                total_unrealized_profit: parseFloat(account.totalUnrealizedProfit),
                total_wallet_balance: parseFloat(account.totalWalletBalance),
            }));
        }
        catch (e) {
            throw serviceErrorHandler(e);
        }
        finally {
            setIsLoading(false);
        }
    }, [
        dispatch,
        pin_code,
        platform_uuid,
        trade_token,
        user,
    ]);
    return {
        getAccountBalanceClient,
        isLoading,
    };
};
export { useGetAccountBalanceClient };
